alter table proposals add column if not exists estimate_type text not null default 'roofing' check (estimate_type in ('roofing','soft_metals','combined')), add column if not exists soft_metal_scopes_snapshot jsonb not null default '[]'::jsonb;
alter table proposal_acceptances add column if not exists selected_scope_snapshots jsonb not null default '[]'::jsonb, add column if not exists declined_scope_snapshots jsonb not null default '[]'::jsonb, add column if not exists scope_colour_selections jsonb not null default '{}'::jsonb;
create or replace function accept_proposal_revision_v2(p_token_id uuid,p_proposal_id uuid,p_revision_id uuid,p_revision integer,p_signer_name text,p_signer_email text,p_signature_type text,p_signature_data text,p_selected_id text,p_selected_snapshot jsonb,p_product text,p_colour text,p_selected_scopes jsonb,p_declined_scopes jsonb,p_scope_colours jsonb,p_subtotal numeric,p_gst numeric,p_total numeric,p_ack jsonb,p_accepted_at timestamptz,p_ip_hash text,p_user_agent text,p_integrity text) returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin perform 1 from proposal_access_tokens where id=p_token_id and proposal_id=p_proposal_id and revision_id=p_revision_id and revoked_at is null and consumed_at is null and expires_at>now() for update;if not found then raise exception 'token unavailable';end if;perform 1 from proposals where id=p_proposal_id and status='sent' and active_revision_id=p_revision_id for update;if not found then raise exception 'proposal unavailable';end if;insert into proposal_acceptances(proposal_id,proposal_revision,revision_id,access_token_id,signer_legal_name,signer_email,signature_type,signature_data,selected_option_id,selected_option_snapshot,selected_product,selected_colour,selected_scope_snapshots,declined_scope_snapshots,scope_colour_selections,subtotal,gst,total,acknowledgement_data,accepted_at,request_ip_hash,user_agent,integrity_hash)values(p_proposal_id,p_revision,p_revision_id,p_token_id,p_signer_name,p_signer_email,p_signature_type,p_signature_data,p_selected_id,p_selected_snapshot,p_product,p_colour,p_selected_scopes,p_declined_scopes,p_scope_colours,p_subtotal,p_gst,p_total,p_ack,p_accepted_at,p_ip_hash,p_user_agent,p_integrity)returning id into v_id;update proposal_access_tokens set consumed_at=now() where id=p_token_id;update proposal_revisions set status='accepted' where id=p_revision_id;update proposals set status='accepted',accepted_at=p_accepted_at,locked_at=now() where id=p_proposal_id;insert into proposal_events(proposal_id,proposal_revision,event_type,actor_type,metadata)values(p_proposal_id,p_revision,'accepted','customer',jsonb_build_object('acceptance_id',v_id));return v_id;end$$;
revoke all on function accept_proposal_revision_v2(uuid,uuid,uuid,integer,text,text,text,text,text,jsonb,text,text,jsonb,jsonb,jsonb,numeric,numeric,numeric,jsonb,timestamptz,text,text,text) from public,anon,authenticated;
grant execute on function accept_proposal_revision_v2(uuid,uuid,uuid,integer,text,text,text,text,text,jsonb,text,text,jsonb,jsonb,jsonb,numeric,numeric,numeric,jsonb,timestamptz,text,text,text) to service_role;
create index if not exists proposals_estimate_type_idx on proposals(estimate_type);
